create sequence if not exists public.customer_code_seq start 1000;
create sequence if not exists public.supplier_code_seq start 100;
alter table public.customers add column if not exists customer_code text unique;
alter table public.suppliers add column if not exists vendor_code text unique;
alter table public.purchase_orders add column if not exists customer_id uuid references public.customers(id) on delete set null;
alter table public.purchase_orders add column if not exists po_number text unique;
update public.customers set customer_code='C'||lpad(nextval('public.customer_code_seq')::text,5,'0') where customer_code is null;
update public.suppliers set vendor_code='V'||lpad(nextval('public.supplier_code_seq')::text,3,'0') where vendor_code is null;
create or replace function public.assign_customer_code() returns trigger language plpgsql as $$ begin if new.customer_code is null then new.customer_code:='C'||lpad(nextval('public.customer_code_seq')::text,5,'0'); end if; return new; end $$;
drop trigger if exists trg_assign_customer_code on public.customers;create trigger trg_assign_customer_code before insert on public.customers for each row execute function public.assign_customer_code();
create or replace function public.assign_vendor_code() returns trigger language plpgsql as $$ begin if new.vendor_code is null then new.vendor_code:='V'||lpad(nextval('public.supplier_code_seq')::text,3,'0'); end if; return new; end $$;
drop trigger if exists trg_assign_vendor_code on public.suppliers;create trigger trg_assign_vendor_code before insert on public.suppliers for each row execute function public.assign_vendor_code();
create or replace function public.create_purchase_order(p_supplier_id uuid,p_customer_id uuid default null,p_notes text default null,p_expected_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_supplier public.suppliers%rowtype;v_customer public.customers%rowtype;v_id uuid;v_date text;v_customer_code text;v_seq integer;v_po text;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;select * into v_supplier from public.suppliers where id=p_supplier_id and active=true;if v_supplier.id is null then raise exception 'supplier not found';end if;if p_customer_id is not null then select * into v_customer from public.customers where id=p_customer_id;if v_customer.id is null then raise exception 'customer not found';end if;v_customer_code:=v_customer.customer_code;else v_customer_code:='STOCK';end if;v_date:=to_char(current_date,'YYMMDD');select coalesce(max(nullif(regexp_replace(po_number,'.*-([0-9]{2})$','\1'),'')::int),0)+1 into v_seq from public.purchase_orders where supplier_id=p_supplier_id and coalesce(customer_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(p_customer_id,'00000000-0000-0000-0000-000000000000'::uuid) and created_at::date=current_date;v_po:=upper(v_supplier.vendor_code)||'-'||v_date||'-'||v_customer_code||'-'||lpad(v_seq::text,2,'0');insert into public.purchase_orders(supplier_id,customer_id,po_number,status,ordered_by,expected_at,notes) values(p_supplier_id,p_customer_id,v_po,'draft',v_user.id,p_expected_at,nullif(trim(p_notes),'')) returning id into v_id;return v_id;end $$;
revoke all on function public.create_purchase_order(uuid,uuid,text,timestamptz) from public,anon;grant execute on function public.create_purchase_order(uuid,uuid,text,timestamptz) to authenticated;
